CREATE TABLE public.pro_visit_checks(visit_id uuid NOT NULL REFERENCES public.visits(id) ON DELETE CASCADE,pro_id uuid NOT NULL,checks jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(visit_id,pro_id));
GRANT SELECT ON public.pro_visit_checks TO authenticated; GRANT ALL ON public.pro_visit_checks TO service_role;
ALTER TABLE public.pro_visit_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "assigned pro own checks" ON public.pro_visit_checks FOR SELECT TO authenticated USING(pro_id=auth.uid() AND public.pro_on_cleaning_team_visit(visit_id,auth.uid()));
CREATE OR REPLACE FUNCTION public.pro_required_check_keys(_service text,_kind text) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _service WHEN 'cleaning' THEN ARRAY['shoe_covers','top_bottom','touchpoints','stainless','glass','microwave','kitchen','baths','bedrooms','living','towels','surface_safe','rotation'] WHEN 'lawn' THEN ARRAY['mow','edge','trim','electric_blower','clippings','beds','gate'] ELSE ARRAY['exterior','wheels','glass_in_out','vacuum','jambs','mats']||CASE WHEN _kind='full_detail' THEN ARRAY['interior_condition','detail_checklist'] ELSE ARRAY[]::text[] END END || ARRAY['locked','alarm','lights_ac','keys_returned'] $$;
CREATE OR REPLACE FUNCTION public.pro_service_checklist(_visit uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; c jsonb; legacy jsonb; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit; IF NOT FOUND OR NOT public.pro_on_cleaning_team_visit(v.id,auth.uid()) THEN RAISE EXCEPTION 'visit_not_assigned'; END IF; SELECT checks INTO c FROM public.pro_visit_checks WHERE visit_id=v.id AND pro_id=auth.uid(); IF v.service::text='cleaning' THEN SELECT checks INTO legacy FROM public.cleaning_visit_checks WHERE visit_id=v.id AND pro_id=auth.uid(); END IF; RETURN jsonb_build_object('keys',public.pro_required_check_keys(v.service::text,v.visit_kind),'checks',coalesce(legacy,'{}'::jsonb)||coalesce(c,'{}'::jsonb),'closed',v.status::text NOT IN ('scheduled','on_the_way','in_progress')); END $$;
CREATE OR REPLACE FUNCTION public.pro_service_check(_visit uuid,_key text,_checked boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit FOR UPDATE; IF NOT FOUND OR NOT public.pro_on_cleaning_team_visit(v.id,auth.uid()) THEN RAISE EXCEPTION 'visit_not_assigned'; END IF; IF v.status::text NOT IN ('scheduled','on_the_way','in_progress') THEN RAISE EXCEPTION 'visit_not_open'; END IF; IF _checked IS NULL OR NOT(_key=ANY(public.pro_required_check_keys(v.service::text,v.visit_kind))) THEN RAISE EXCEPTION 'invalid_check'; END IF; INSERT INTO public.pro_visit_checks(visit_id,pro_id,checks) VALUES(v.id,auth.uid(),jsonb_build_object(_key,_checked)) ON CONFLICT(visit_id,pro_id) DO UPDATE SET checks=pro_visit_checks.checks||excluded.checks,updated_at=now(); IF v.service::text='cleaning' AND _key IN ('touchpoints','stainless','glass','microwave','towels','shoe_covers','surface_safe','rotation','locked','alarm','lights_ac','keys_returned') THEN INSERT INTO public.cleaning_visit_checks(visit_id,pro_id,checks) VALUES(v.id,auth.uid(),jsonb_build_object(_key,_checked)) ON CONFLICT(visit_id,pro_id) DO UPDATE SET checks=cleaning_visit_checks.checks||excluded.checks,updated_at=now(); END IF; END $$;
CREATE OR REPLACE FUNCTION public.pro_required_checklist_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p uuid; c jsonb; legacy jsonb; k text; BEGIN IF NEW.status::text='complete' AND OLD.status::text<>'complete' AND NOT coalesce(NEW.is_sample,false) THEN FOR p IN SELECT NEW.assigned_pro_id UNION SELECT coalesce(NEW.backup_pro_id,t.partner_pro_id) FROM public.cleaning_teams t WHERE t.id=NEW.cleaning_team_id AND t.kind='paired_pros' AND NEW.size_tier=5 LOOP IF p IS NULL THEN RAISE EXCEPTION 'pro_assignment_required'; END IF; c:=NULL;legacy:=NULL; SELECT checks INTO c FROM public.pro_visit_checks WHERE visit_id=NEW.id AND pro_id=p; IF NEW.service::text='cleaning' THEN SELECT checks INTO legacy FROM public.cleaning_visit_checks WHERE visit_id=NEW.id AND pro_id=p; END IF; c:=coalesce(legacy,'{}'::jsonb)||coalesce(c,'{}'::jsonb); FOREACH k IN ARRAY public.pro_required_check_keys(NEW.service::text,NEW.visit_kind) LOOP IF NOT coalesce((c->>k)::boolean,false) THEN RAISE EXCEPTION 'service_checklist_required:%',k; END IF; END LOOP; END LOOP; IF EXISTS(SELECT 1 FROM public.addon_attaches a WHERE a.visit_id=NEW.id AND a.status='pending_visit') THEN RAISE EXCEPTION 'booked_addons_incomplete'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_pro_required_checklist BEFORE UPDATE ON public.visits FOR EACH ROW EXECUTE FUNCTION public.pro_required_checklist_guard();
REVOKE ALL ON FUNCTION public.pro_service_checklist(uuid),public.pro_service_check(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pro_service_checklist(uuid),public.pro_service_check(uuid,text,boolean) TO authenticated;